/**
 * Reads, filters and counts the Relume component inventory for the
 * development-only browse page at /dev/relume, and writes the decisions file.
 *
 * Two files at the repo root feed it:
 * - `relume/inventory.json` (generated by `pnpm relume:inventory`, gitignored):
 *   one record per catalogue entry with its status.
 * - `relume/decisions.json` (committed): `{ "<slug>": "want" | "skip" }`.
 *
 * The inventory's own `decision` field is a snapshot taken when it was
 * generated, so it goes stale as soon as a decision changes. Every read overlays
 * decisions.json on the records: that file is the source of truth.
 */
import "server-only";
import { existsSync, readFileSync, renameSync, writeFileSync } from "node:fs";
import path from "node:path";

export const STATUSES = [
  "not-pulled",
  "convertible",
  "needs-judgment",
  "converted",
] as const;
export type Status = (typeof STATUSES)[number];

export const DECISIONS = ["want", "skip"] as const;
export type Decision = (typeof DECISIONS)[number];

/** Decision filter values; "undecided" means no entry in decisions.json. */
export const DECISION_FILTERS = ["want", "skip", "undecided"] as const;
export type DecisionFilter = (typeof DECISION_FILTERS)[number];

export const STATUS_LABELS: Record<Status, string> = {
  "not-pulled": "Not pulled",
  convertible: "Convertible",
  "needs-judgment": "Needs judgment",
  converted: "Converted",
};

export const DECISION_LABELS: Record<DecisionFilter, string> = {
  want: "Want",
  skip: "Skip",
  undecided: "Undecided",
};

export type InventoryRecord = {
  slug: string;
  name: string;
  category: string;
  tags: string[];
  preview: string;
  /** Relume's "uncommon" flag, from the library MCP. */
  uncommon: boolean;
  /** Relume's layout styles ("standard", "off_grid", ...); can be empty. */
  layoutStyle: string[];
  status: Status;
  reasons: string[];
  decision: Decision | null;
};

export type Decisions = Record<string, Decision>;

export type InventoryResult =
  | { state: "ok"; generatedAt: string; components: InventoryRecord[] }
  | { state: "missing"; path: string }
  | {
      state: "invalid";
      /** Which file failed: regenerating repairs only the inventory. */
      source: "inventory" | "decisions";
      path: string;
      error: string;
    };

export type StatusCounts = Record<Status, number>;

export type CategorySummary = {
  category: string;
  label: string;
  total: number;
  counts: StatusCounts;
};

/**
 * The category page's filters, all kept in the URL. `layout` and `element`
 * hold tags; the toggles narrow to components with the flag when on and show
 * everything when off.
 */
export type Filters = {
  status: Status | null;
  decision: DecisionFilter | null;
  layout: string[];
  element: string[];
  offGrid: boolean;
  uncommon: boolean;
  interactions: boolean;
};

const SLUG_PATTERN = /^[a-z0-9][a-z0-9-]*$/;

export const INVENTORY_COMMAND = "pnpm relume:inventory";

/** The browse page and the decisions action only run under `next dev`. */
export function isDevelopment() {
  return process.env.NODE_ENV === "development";
}

/**
 * Walks up from `start` (the dev server runs with cwd frontend/) to the
 * directory holding pnpm-workspace.yaml.
 *
 * Callers use it only under `next dev`, but /block-library imports this
 * module in production too. The ignore comment keeps the build's file tracer
 * from reading this lookup as "the server may read any file" and copying the
 * whole project into the route's server output.
 */
export function findRepoRoot(start: string = process.cwd()) {
  let dir = path.resolve(/* turbopackIgnore: true */ start);
  for (;;) {
    if (existsSync(path.join(dir, "pnpm-workspace.yaml"))) return dir;
    const parent = path.dirname(dir);
    if (parent === dir) {
      throw new Error(
        `Could not find the repo root (pnpm-workspace.yaml) above ${start}`,
      );
    }
    dir = parent;
  }
}

export function inventoryPath(root: string) {
  return path.join(root, "relume", "inventory.json");
}

export function decisionsPath(root: string) {
  return path.join(root, "relume", "decisions.json");
}

export function isStatus(value: unknown): value is Status {
  return typeof value === "string" && (STATUSES as readonly string[]).includes(value);
}

export function isDecision(value: unknown): value is Decision {
  return typeof value === "string" && (DECISIONS as readonly string[]).includes(value);
}

export function isSlug(value: unknown): value is string {
  return typeof value === "string" && SLUG_PATTERN.test(value);
}

/** A missing file means no decisions. Unknown values are ignored. */
export function readDecisions(root: string): Decisions {
  const file = decisionsPath(root);
  if (!existsSync(file)) return {};
  const parsed: unknown = JSON.parse(readFileSync(file, "utf8"));
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw new Error(`${file} must hold a JSON object of slug to decision`);
  }
  const decisions: Decisions = {};
  for (const [slug, decision] of Object.entries(parsed)) {
    if (isDecision(decision)) decisions[slug] = decision;
  }
  return decisions;
}

/** Keys sorted, 2-space indent, trailing newline. */
export function serializeDecisions(decisions: Decisions) {
  const sorted: Decisions = {};
  for (const slug of Object.keys(decisions).sort()) {
    sorted[slug] = decisions[slug];
  }
  return `${JSON.stringify(sorted, null, 2)}\n`;
}

/**
 * Sets one slug's decision, or removes its entry when `decision` is null
 * (Clear). Returns the decisions as written.
 */
export function writeDecision(
  root: string,
  slug: string,
  decision: Decision | null,
): Decisions {
  if (!isSlug(slug)) throw new Error(`Invalid Relume slug: ${String(slug)}`);
  if (decision !== null && !isDecision(decision)) {
    throw new Error(`Invalid decision: ${String(decision)}`);
  }
  const decisions = readDecisions(root);
  if (decision === null) delete decisions[slug];
  else decisions[slug] = decision;

  const file = decisionsPath(root);
  const temp = `${file}.${process.pid}.tmp`;
  writeFileSync(temp, serializeDecisions(decisions));
  renameSync(temp, file);
  return decisions;
}

/** decisions.json wins over the decision stored in the inventory. */
export function applyDecisions(
  components: InventoryRecord[],
  decisions: Decisions,
): InventoryRecord[] {
  return components.map((component) => ({
    ...component,
    decision: decisions[component.slug] ?? null,
  }));
}

function normalizeRecord(raw: unknown): InventoryRecord | null {
  if (!raw || typeof raw !== "object") return null;
  const record = raw as Record<string, unknown>;
  if (typeof record.slug !== "string" || typeof record.category !== "string") {
    return null;
  }
  return {
    slug: record.slug,
    name: typeof record.name === "string" ? record.name : record.slug,
    category: record.category,
    tags: Array.isArray(record.tags)
      ? record.tags.filter((tag): tag is string => typeof tag === "string")
      : [],
    preview: typeof record.preview === "string" ? record.preview : "",
    uncommon: record.uncommon === true,
    layoutStyle: Array.isArray(record.layoutStyle)
      ? record.layoutStyle.filter((style): style is string => typeof style === "string")
      : [],
    status: isStatus(record.status) ? record.status : "not-pulled",
    reasons: Array.isArray(record.reasons)
      ? record.reasons.filter((reason): reason is string => typeof reason === "string")
      : [],
    decision: isDecision(record.decision) ? record.decision : null,
  };
}

/** Reads both files from disk on every call, with decisions overlaid. */
export function loadInventory(root: string): InventoryResult {
  const file = inventoryPath(root);
  if (!existsSync(file)) return { state: "missing", path: file };
  const message = (error: unknown) =>
    error instanceof Error ? error.message : String(error);
  let generatedAt: string;
  let components: InventoryRecord[];
  try {
    const parsed = JSON.parse(readFileSync(file, "utf8")) as {
      generatedAt?: unknown;
      components?: unknown;
    };
    if (!Array.isArray(parsed.components)) {
      throw new Error("it has no components array");
    }
    generatedAt = typeof parsed.generatedAt === "string" ? parsed.generatedAt : "";
    components = parsed.components
      .map(normalizeRecord)
      .filter((record): record is InventoryRecord => record !== null);
  } catch (error) {
    return { state: "invalid", source: "inventory", path: file, error: message(error) };
  }
  try {
    return {
      state: "ok",
      generatedAt,
      components: applyDecisions(components, readDecisions(root)),
    };
  } catch (error) {
    return {
      state: "invalid",
      source: "decisions",
      path: decisionsPath(root),
      error: message(error),
    };
  }
}

const UPPERCASE_WORDS = new Set(["cta", "faq"]);

/** "feature-sections" -> "Feature Sections", "cta-sections" -> "CTA Sections". */
export function categoryLabel(category: string) {
  return category
    .split("-")
    .filter(Boolean)
    .map((word) =>
      UPPERCASE_WORDS.has(word)
        ? word.toUpperCase()
        : word.charAt(0).toUpperCase() + word.slice(1),
    )
    .join(" ");
}

export function emptyCounts(): StatusCounts {
  return { "not-pulled": 0, convertible: 0, "needs-judgment": 0, converted: 0 };
}

export function countStatuses(components: InventoryRecord[]): StatusCounts {
  const counts = emptyCounts();
  for (const component of components) counts[component.status] += 1;
  return counts;
}

/** One row per category, largest first, then by label. */
export function summarizeCategories(components: InventoryRecord[]): CategorySummary[] {
  const byCategory = new Map<string, InventoryRecord[]>();
  for (const component of components) {
    const list = byCategory.get(component.category) ?? [];
    list.push(component);
    byCategory.set(component.category, list);
  }
  return [...byCategory.entries()]
    .map(([category, list]) => ({
      category,
      label: categoryLabel(category),
      total: list.length,
      counts: countStatuses(list),
    }))
    .sort((a, b) => b.total - a.total || a.label.localeCompare(b.label));
}

/*
 * Tag filters, as Relume's library site groups them on a category page:
 * "Layout" (checkbox groups plus the Off-grid toggle), "Element" (every other
 * tag) and "More Filters" (the Uncommon and Interactions toggles).
 *
 * The groups are decided by the tag's name, from the catalogue's real tag
 * vocabulary. Some tags name the kind of Relume component rather than something in it
 * ("CTA Section", "Hero Header Section", "Announcement Banner", "Navbar");
 * those are block-type labels and are offered in neither list.
 */

export type LayoutGroupId = "text" | "content" | "columns" | "logo" | "menu" | "filter";

type LayoutGroupRule = {
  id: LayoutGroupId;
  label: string;
  /** Options in this order; a tag not listed sorts after them by name. */
  order: string[];
  match: (tag: string) => boolean;
};

const COLUMNS_PATTERN = /^(\d+)\+? Columns?$/;

export const LAYOUT_GROUPS: LayoutGroupRule[] = [
  {
    id: "text",
    label: "Text Alignment",
    order: ["Text Align Left", "Text Align Center", "Text Align Right"],
    match: (tag) => tag.startsWith("Text Align "),
  },
  {
    id: "content",
    label: "Content Alignment",
    order: [
      "Image/Video Left",
      "Image/Video Center",
      "Image/Video Right",
      "Image/Video Bottom",
      "Image/Video Top",
    ],
    match: (tag) => /^Image\/Video (Left|Center|Right|Bottom|Top)$/.test(tag),
  },
  {
    id: "columns",
    label: "Columns",
    order: [],
    match: (tag) => COLUMNS_PATTERN.test(tag),
  },
  // Not on the Hero or Banner pages Relume showed; named the way Relume names
  // "Text Align Left" -> "Text Alignment".
  {
    id: "logo",
    label: "Logo Alignment",
    order: ["Logo Left", "Logo Center"],
    match: (tag) => /^Logo (Left|Center|Right)$/.test(tag),
  },
  {
    id: "menu",
    label: "Menu Alignment",
    order: ["Menu Left", "Menu Center", "Menu Right"],
    match: (tag) => /^Menu (Left|Center|Right)$/.test(tag),
  },
  {
    id: "filter",
    label: "Filter Position",
    order: ["Filter Top", "Filter Left"],
    match: (tag) => /^Filter (Top|Left|Right)$/.test(tag),
  },
];

const BLOCK_TYPE_NAMES = new Set(["Navbar", "Footer"]);

/** "CTA Section", "Marquee Banner", "Navbar": what the Relume component is, not what is in it. */
export function isBlockTypeTag(tag: string) {
  return / (Section|Banner)$/.test(tag) || BLOCK_TYPE_NAMES.has(tag);
}

export type TagKind =
  | { kind: "layout"; group: LayoutGroupId }
  | { kind: "element" }
  | { kind: "block-type" };

export function classifyTag(tag: string): TagKind {
  const group = LAYOUT_GROUPS.find((rule) => rule.match(tag));
  if (group) return { kind: "layout", group: group.id };
  if (isBlockTypeTag(tag)) return { kind: "block-type" };
  return { kind: "element" };
}

/**
 * Relume's "Interactions" flag. The library MCP does not return it, but Relume
 * previews exactly those components (animations, scroll effects) with an
 * animated GIF instead of a still image, so the preview's file type stands in.
 */
export function hasInteractions(component: Pick<InventoryRecord, "preview">) {
  return /\.gif(?:[?#]|$)/i.test(component.preview);
}

export function isOffGrid(component: Pick<InventoryRecord, "layoutStyle">) {
  return component.layoutStyle.includes("off_grid");
}

export type FilterOption = { tag: string; count: number };

export type FilterOptions = {
  layoutGroups: { id: LayoutGroupId; label: string; options: FilterOption[] }[];
  elements: FilterOption[];
  /** How many components are off-grid; 0 hides the toggle. */
  offGrid: number;
  uncommon: number;
  interactions: number;
};

function countTags(components: InventoryRecord[]) {
  const counts = new Map<string, number>();
  for (const component of components) {
    for (const tag of new Set(component.tags)) {
      counts.set(tag, (counts.get(tag) ?? 0) + 1);
    }
  }
  return counts;
}

function layoutOrder(rule: LayoutGroupRule, a: string, b: string) {
  if (rule.id === "columns") {
    return Number(a.match(COLUMNS_PATTERN)?.[1]) - Number(b.match(COLUMNS_PATTERN)?.[1]);
  }
  const rank = (tag: string) => {
    const index = rule.order.indexOf(tag);
    return index === -1 ? rule.order.length : index;
  };
  return rank(a) - rank(b) || a.localeCompare(b);
}

/**
 * The options one category offers: only groups and tags that occur in it.
 * Counts are over the whole category. A tag selected in `filters` that the
 * category lacks is listed with a count of 0, so it can be unticked.
 */
export function filterOptions(
  components: InventoryRecord[],
  filters?: Pick<Filters, "layout" | "element">,
): FilterOptions {
  const counts = countTags(components);
  for (const tag of [...(filters?.layout ?? []), ...(filters?.element ?? [])]) {
    if (!counts.has(tag)) counts.set(tag, 0);
  }
  const tags = [...counts.keys()];
  const layoutGroups = LAYOUT_GROUPS.map((rule) => ({
    id: rule.id,
    label: rule.label,
    options: tags
      .filter((tag) => rule.match(tag))
      .sort((a, b) => layoutOrder(rule, a, b))
      .map((tag) => ({ tag, count: counts.get(tag) ?? 0 })),
  })).filter((group) => group.options.length);
  const elements = tags
    .filter((tag) => classifyTag(tag).kind === "element")
    .map((tag) => ({ tag, count: counts.get(tag) ?? 0 }))
    .sort((a, b) => b.count - a.count || a.tag.localeCompare(b.tag));
  return {
    layoutGroups,
    elements,
    offGrid: components.filter(isOffGrid).length,
    uncommon: components.filter((component) => component.uncommon).length,
    interactions: components.filter(hasInteractions).length,
  };
}

type SearchParamValue = string | string[] | undefined;

function firstValue(value: SearchParamValue) {
  return Array.isArray(value) ? value[0] : value;
}

function allValues(value: SearchParamValue) {
  const values = Array.isArray(value) ? value : value === undefined ? [] : [value];
  return [...new Set(values.map((entry) => entry.trim()).filter(Boolean))];
}

function isOn(value: SearchParamValue) {
  const first = firstValue(value);
  return first === "1" || first === "true";
}

/**
 * Reads the category page's search params. Unknown values are dropped rather
 * than matching nothing: a layout value must be a layout tag, an element value
 * must not be one (nor a block-type label).
 */
export function parseFilters(searchParams: Record<string, SearchParamValue>): Filters {
  const status = firstValue(searchParams.status);
  const decision = firstValue(searchParams.decision);
  return {
    status: isStatus(status) ? status : null,
    decision:
      decision && (DECISION_FILTERS as readonly string[]).includes(decision)
        ? (decision as DecisionFilter)
        : null,
    layout: allValues(searchParams.layout).filter((tag) => classifyTag(tag).kind === "layout"),
    element: allValues(searchParams.element).filter(
      (tag) => classifyTag(tag).kind === "element",
    ),
    offGrid: isOn(searchParams.offGrid),
    uncommon: isOn(searchParams.uncommon),
    interactions: isOn(searchParams.interactions),
  };
}

export function matchesDecision(
  decision: Decision | null,
  filter: DecisionFilter | null,
) {
  if (!filter) return true;
  if (filter === "undecided") return decision === null;
  return decision === filter;
}

/**
 * Ticked layout tags are OR within their group and AND across groups; ticked
 * elements must all be present (AND); every other filter is AND.
 */
export function matchesLayout(tags: string[], layout: string[]) {
  const byGroup = new Map<LayoutGroupId, string[]>();
  for (const tag of layout) {
    const kind = classifyTag(tag);
    if (kind.kind !== "layout") continue;
    byGroup.set(kind.group, [...(byGroup.get(kind.group) ?? []), tag]);
  }
  return [...byGroup.values()].every((group) => group.some((tag) => tags.includes(tag)));
}

export function filterComponents(
  components: InventoryRecord[],
  filters: Filters,
): InventoryRecord[] {
  return components.filter(
    (component) =>
      (!filters.status || component.status === filters.status) &&
      matchesDecision(component.decision, filters.decision) &&
      matchesLayout(component.tags, filters.layout) &&
      filters.element.every((tag) => component.tags.includes(tag)) &&
      (!filters.offGrid || isOffGrid(component)) &&
      (!filters.uncommon || component.uncommon) &&
      (!filters.interactions || hasInteractions(component)),
  );
}

export const NO_FILTERS: Filters = {
  status: null,
  decision: null,
  layout: [],
  element: [],
  offGrid: false,
  uncommon: false,
  interactions: false,
};

/** Adds `value` to the list, or removes it when it is there. */
export function toggleValue(list: string[], value: string) {
  return list.includes(value) ? list.filter((entry) => entry !== value) : [...list, value];
}

/** How many selections each control on the page holds, for its button. */
export function activeCounts(filters: Filters) {
  return {
    status: filters.status ? 1 : 0,
    decision: filters.decision ? 1 : 0,
    layout: filters.layout.length + (filters.offGrid ? 1 : 0),
    element: filters.element.length,
    more: (filters.uncommon ? 1 : 0) + (filters.interactions ? 1 : 0),
  };
}

/** Builds a category page URL; an empty value drops its key. */
export function filterHref(
  basePath: string,
  filters: Filters,
  change: Partial<Filters> = {},
) {
  const next = { ...filters, ...change };
  const params = new URLSearchParams();
  if (next.status) params.set("status", next.status);
  if (next.decision) params.set("decision", next.decision);
  for (const tag of next.layout) params.append("layout", tag);
  for (const tag of next.element) params.append("element", tag);
  if (next.offGrid) params.set("offGrid", "1");
  if (next.uncommon) params.set("uncommon", "1");
  if (next.interactions) params.set("interactions", "1");
  const query = params.toString();
  return query ? `${basePath}?${query}` : basePath;
}

/** The URL that toggles one tag from a card or a menu, in its own list. */
export function toggleTagHref(basePath: string, filters: Filters, tag: string) {
  const kind = classifyTag(tag).kind;
  if (kind === "layout") return filterHref(basePath, filters, { layout: toggleValue(filters.layout, tag) });
  if (kind === "element") return filterHref(basePath, filters, { element: toggleValue(filters.element, tag) });
  return null;
}
